    cudaFuncSetAttribute(tc_h_kernel<G>, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn);
    attr_set = true;
  }
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(2 * (kN / (2 * kRows)) * p.nb);
  cfg.blockDim = dim3((kCvtWarp0 + kGroupWarps * G) * 32);
  cfg.dynamicSmemBytes = p.stages * (kABlk + p.ntile / 2 * 128) + 1024;
  cfg.stream = stream;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension;
  at[0].val.clusterDim.x = 2;
  at[0].val.clusterDim.y = 1;
  at[0].val.clusterDim.z = 1;
  cfg.attrs = at;
  cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_h_kernel<G>, W, emb, (uint4*)emb16, m1, m2, bias, op, p);
  return (int)cudaGetLastError();
}
}  // namespace

extern "C" int adamod_tc_h_cfg(const float* emb, const float* W, const float* bias, float* const* outs, void* emb16, int B,
                               int G, int maxStages, int inkern, cudaStream_t stream) {
  if (B < 1 || B > 1024 || emb16 == nullptr || (G != 2 && G != 3)) return 430;
  TileCfg p;
  p.B = B;
  p.nb = B <= 512 ? 1 : 2;
  p.ntile = ((B + p.nb - 1) / p.nb + 15) / 16 * 16;
  p.n1 = p.ntile < 256 ? p.ntile : 256;
  p.n2 = p.ntile - p.n1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
  const int embBytes = p.ntile / 2 * 128, stageBytes = kABlk + embBytes;
  p.stages = (kSmemDyn - 1024) / stageBytes;
  if (p.stages > maxStages) p.stages = maxStages;
  if (p.stages > kMaxStages) p.stages = kMaxStages;
  if (p.stages < G) return 433;
  p.inkern = inkern;
  p.chunk = embBytes / 4 / 8 * 8;
  if (p.chunk > 8192) p.chunk = 8192;
  p.nT = (B * kD + p.chunk - 1) / p.chunk;
  CUtensorMap mE1, mE2;
  cuuint32_t es[2] = {1, 1};
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 2};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(p.n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)(p.n2 ? p.n2 / 2 : 8)};
  if (cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 431;
  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, emb16, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 432;
  if (!inkern) {
    const int n8 = B * kD / 8;
    emb_f16_kernel<<<(n8 + 255) / 256, 256, 0, stream>>>(emb, (uint4*)emb16, n8);
  }
  OutPtrs op;
  for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  if (G == 2) return launch_g<2>(W, emb, emb16, mE1, mE2, bias, op, p, stream);
  return launch_g<3>(W, emb, emb16, mE1, mE2, bias, op, p, stream);
}
