__device__ __forceinline__ bool try_wait(uint32_t bar, uint32_t par) { uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }" : "=r"(ok) : "r"(bar), "r"(par) : "memory"); return ok != 0; }
__device__ __forceinline__ bool try_wait_cluster(uint32_t bar, uint32_t par) { uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.acquire.cluster.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }" : "=r"(ok) : "r"(bar), "r"(par) : "memory"); return ok != 0; }
__device__ __forceinline__ void mbar_wait(uint32_t bar, uint32_t par) { uint32_t n = 0; while (!try_wait(bar, par)) if (++n > (1u << 27)) __trap(); }
__device__ __forceinline__ void mbar_wait_cluster(uint32_t bar, uint32_t par) { uint32_t n = 0; while (!try_wait_cluster(bar, par)) if (++n > (1u << 27)) __trap(); }
__device__ __forceinline__ void mbar_init(uint32_t bar, uint32_t count) { asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(bar), "r"(count)); }
__device__ __forceinline__ uint32_t elect_one() { uint32_t pred = 0;
